const OLD_FILES=[{"id":"FIL-EFFB9834","name":"F0106-PD-rebar-original.pdf","sha256":"ae8b16439650526a5ef6e1975c852fa38c2ab4466cd73ab725a47bcb32a6b655","size":23871472,"stages":["PD"],"pageCount":139,"registeredAt":"2026-10-17T23:08:21.223Z","review":null},{"id":"FIL-4D91EF2A","name":"F0139-RD-rebar-original.pdf","sha256":"d59c225e75d1e0227f08869b31165bd93bf85ed4b1da005c3e86ebc27023b73f","size":2298875,"stages":["RD"],"pageCount":22,"registeredAt":"2026-10-17T23:08:21.504Z","review":null}] as SourceFileSummary[];

const nodes=(node:any,type:string):React.ReactElement<any>[]=>{
 const found:React.ReactElement<any>[]=[];
 const walk=(value:any)=>{if(!isValidElement(value))return;const element=value as React.ReactElement<any>;
  if(element.type===type)found.push(element);React.Children.forEach(element.props.children,walk);};
 walk(node);return found;
};
const text=(node:any):string=>{if(node==null||typeof node==='boolean')return'';if(typeof node==='string'||typeof node==='number')return String(node);if(Array.isArray(node))return node.map(text).join('');if(isValidElement(node))return text((node as React.ReactElement<any>).props.children);return'';};
const view=(filter:MatrixReviewWorkView['filter']='ALL',factsFirst=false):MatrixReviewWorkView=>({filter,factsFirst});
const tree=(selected:MatrixReviewWorkView=view(),data:MatrixExecutionRead=REAL,events:any[]=[])=>(MatrixReviewWorklist({data,files:OLD_FILES,view:selected,onViewChange:v=>events.push(['view',v]),onSelect:(...v)=>events.push(['fact',...v]),onSource:v=>events.push(['source',v])}));
const summaries=(node:any)=>nodes(node,'summary').map(e=>text(e.props.children)).filter(s=>/^[A-Z][A-Z0-9]*-\d{3} · /u.test(s));
const codes=(node:any)=>summaries(node).map(s=>s.split(' · ')[0]);
const realCodes=REAL.execution.results.map(r=>r.parameterCode);
const control=(node:any,type:string)=>{const found=nodes(node,type);assert.equal(found.length,1);return found[0];};
const chooser=(files:SourceFileSummary[]=OLD_FILES,addressValid=true,events:any[]=[])=>(MatrixReviewSourceChooser({files,addressValid,onSource:file=>events.push(file)}));
const invalidData=()=>{const d=clone(REAL);d.execution.results[0].ruleId='not-installed';return d;};

describe('controlled saved-result presentation, manually enumerated T48 populations',()=>{
 it('pure default has all63 in exact saved order',()=>{assert.deepEqual(codes(MatrixReviewWorklist({data:REAL,files:OLD_FILES,onSelect:()=>{}})),realCodes);});
 it('controlled BOTH contains only original KR055 and KR057',()=>{assert.deepEqual(codes(tree(view('BOTH_STAGES'))),['KR-055','KR-057']);});
 it('controlled ONE contains exactly original four in saved order',()=>{assert.deepEqual(codes(tree(view('ONE_STAGE'))),['PZ-008','PZ-009','PZ-022','KR-059']);});
 it('controlled NONE contains other57 original results',()=>{assert.deepEqual(codes(tree(view('NO_FACTS'))),realCodes.filter((_,i)=>![3,4,13,32,33,35].includes(i)));});
 it('invalid installed-rule row remains visible for every filter',()=>{for(const filter of ['ALL','BOTH_STAGES','ONE_STAGE','NO_FACTS'] as const){const c=codes(tree(view(filter),invalidData()));assert.equal(c[0],'PZ-002');assert.equal(c.length,{ALL:63,BOTH_STAGES:3,ONE_STAGE:5,NO_FACTS:57}[filter]);}});
 it('factsFirst retains manual priority prefix and saved order for remaining rows',()=>{assert.deepEqual(codes(tree(view('ALL',true))),[32,33,3,4,13,35,...realCodes.map((_,i)=>i).filter(i=>![32,33,3,4,13,35].includes(i))].map(i=>realCodes[i]));});
 it('controlled rerender applies emitted filter without changing saved data',()=>{const events:any[]=[],before=clone(REAL),first=tree(view(),REAL,events);control(first,'select').props.onChange({target:{value:'BOTH_STAGES'}});assert.deepEqual(events,[['view',view('BOTH_STAGES')]]);const rerender=tree(events[0][1] as MatrixReviewWorkView);assert.deepEqual(codes(rerender),['KR-055','KR-057']);assert.deepEqual(REAL,before);assert.equal(codes(first).length,63);});
 it('controls expose exact labels and controlled values',()=>{const t=tree(view('ONE_STAGE',true));assert.equal(control(t,'select').props.value,'ONE_STAGE');assert.equal(control(t,'input').props.checked,true);const labels=nodes(t,'label').map(e=>text(e.props.children));assert.ok(labels.some(s=>s.startsWith('Наличие исходных фактов')));assert.ok(labels.includes('Сначала с исходными фактами'));assert.deepEqual(nodes(t,'option').map(e=>[e.props.value,text(e.props.children)]),[['ALL','Все результаты'],['BOTH_STAGES','Факты обеих стадий'],['ONE_STAGE','Факты одной стадии'],['NO_FACTS','Без исходных фактов']]);});
 it('dropdown emits each exact view and preserves current sort only',()=>{for(const filter of ['ALL','BOTH_STAGES','ONE_STAGE','NO_FACTS'] as const){const events:any[]=[],current=view('ONE_STAGE',true),before=clone(current),t=tree(current,REAL,events);control(t,'select').props.onChange({target:{value:filter}});assert.deepEqual(events,[['view',view(filter,true)]]);assert.deepEqual(current,before);}});
 it('unknown dropdown value emits nothing',()=>{const events:any[]=[],t=tree(view(),REAL,events);control(t,'select').props.onChange({target:{value:'CANDIDATE'}});assert.deepEqual(events,[]);});
 it('checkbox emits exact checked state preserving filter, no source or fact effects',()=>{for(const checked of [true,false]){const events:any[]=[],t=tree(view('NO_FACTS',!checked),REAL,events);control(t,'input').props.onChange({target:{checked}});assert.deepEqual(events,[['view',view('NO_FACTS',checked)]]);}});
 it('optional onViewChange allows read-only render and inert controls',()=>{const events:any[]=[],t=MatrixReviewWorklist({data:REAL,files:OLD_FILES,onSelect:()=>events.push('fact'),onSource:()=>events.push('source')});control(t,'select').props.onChange({target:{value:'ONE_STAGE'}});control(t,'input').props.onChange({target:{checked:true}});assert.deepEqual(events,[]);});
 it('pure render has one chooser element without descending component evaluation',()=>{const t=tree();let count=0;const walk=(n:any)=>{if(!isValidElement(n))return;const e=n as React.ReactElement<any>;if(e.type===MatrixReviewSourceChooser)count++;React.Children.forEach(e.props.children,walk);};walk(t);assert.equal(count,1);assert.equal(nodes(t,'button').filter(b=>text(b.props.children).startsWith('Проверить источник:')).length,0);});
});

describe('explicit detached source chooser actions',()=>{
 it('single chooser shows each exact safe file ID and original SHA',()=>{const t=chooser();assert.deepEqual(nodes(t,'summary').map(s=>text(s.props.children)),['Искать в исходных файлах']);assert.deepEqual(nodes(t,'button').map(b=>text(b.props.children)),OLD_FILES.map(f=>'Проверить источник: '+f.name));const raw=text(t);for(const f of OLD_FILES){assert.ok(raw.includes(f.id));assert.ok(raw.includes(f.sha256));}});
 it('no callback until explicit exact-ID+SHA button click',()=>{const events:any[]=[],files=clone(OLD_FILES),before=clone(files),t=chooser(files,true,events),bs=nodes(t,'button');assert.deepEqual(events,[]);for(let i=0;i<bs.length;i++){assert.equal(bs[i].props.type,'button');assert.equal(bs[i].props.disabled,false);bs[i].props.onClick();assert.deepEqual(events[i],{id:files[i].id,sha256:files[i].sha256});assert.deepEqual(Object.keys(events[i]).sort(),['id','sha256']);}assert.deepEqual(files,before);});
 it('invalid address disables DOM and independently guards every handler',()=>{const events:any[]=[],bs=nodes(chooser(OLD_FILES,false,events),'button');assert.equal(bs.length,2);for(const b of bs){assert.equal(b.props.disabled,true);b.props.onClick();}assert.deepEqual(events,[]);});
 it('omitted callback disables DOM and guards handlers',()=>{const t=MatrixReviewSourceChooser({files:OLD_FILES,addressValid:true});for(const b of nodes(t,'button')){assert.equal(b.props.disabled,true);assert.doesNotThrow(()=>b.props.onClick());}});
 it('duplicate IDs excluded completely even if SHA differs',()=>{for(const duplicate of [clone(OLD_FILES[0]),{...clone(OLD_FILES[0]),sha256:'0'.repeat(64)}]){const events:any[]=[],bs=nodes(chooser([...OLD_FILES,duplicate],true,events),'button');assert.equal(bs.length,1);assert.equal(text(bs[0].props.children),'Проверить источник: '+OLD_FILES[1].name);bs[0].props.onClick();assert.deepEqual(events,[{id:OLD_FILES[1].id,sha256:OLD_FILES[1].sha256}]);}});
 it('unsafe IDs and malformed uppercase/non64 SHA have no actions',()=>{const bads=[{...OLD_FILES[0],id:'../source'},{...OLD_FILES[0],id:'x'.repeat(201)},{...OLD_FILES[0],id:''},{...OLD_FILES[0],id:'SPACES ID'},{...OLD_FILES[0],sha256:OLD_FILES[0].sha256.toUpperCase()},{...OLD_FILES[0],sha256:'abc'}];for(const f of bads)assert.equal(nodes(chooser([f]),'button').length,0);});
 it('chooser respects input file order without approval or stage mapping',()=>{const files=clone(OLD_FILES).reverse();files[0].stages=[];files[1].stages=['ID'];const events:any[]=[],bs=nodes(chooser(files,true,events),'button');assert.deepEqual(bs.map(b=>text(b.props.children)),files.map(f=>'Проверить источник: '+f.name));bs[0].props.onClick();assert.deepEqual(events,[{id:files[0].id,sha256:files[0].sha256}]);});
 it('invalid saved address reaches chooser as false, without changing source choice visibility',()=>{for(const mutation of [{checkId:''},{contentHash:'bad'}]){const d={...clone(REAL),...mutation};const t=tree(view(),d);let choice:React.ReactElement<any>|undefined;const walk=(n:any)=>{if(!isValidElement(n))return;const e=n as React.ReactElement<any>;if(e.type===MatrixReviewSourceChooser)choice=e;React.Children.forEach(e.props.children,walk);};walk(t);assert.ok(choice);assert.equal(choice.props.addressValid,false);const rendered=MatrixReviewSourceChooser(choice.props);assert.equal(nodes(rendered,'button').length,2);assert.ok(nodes(rendered,'button').every(b=>b.props.disabled));}});
});

describe('controller lifecycle boundary, structural and SSR only',()=>{
 it('controller inner React identity is exact check+content hash',()=>{const a=MatrixReviewWorklistController({data:REAL,files:OLD_FILES,onSelect:()=>{}});assert.equal(a.key,JSON.stringify([REAL.checkId,REAL.contentHash]));assert.equal(a.props.data,REAL);assert.equal(a.props.files,OLD_FILES);assert.equal(typeof a.type,'function');});
 it('same saved address retains key; either changed address field produces different key',()=>{const make=(data:MatrixExecutionRead)=>MatrixReviewWorklistController({data,files:OLD_FILES,onSelect:()=>{}});const original=make(REAL);assert.equal(make(clone(REAL)).key,original.key);assert.notEqual(make({...clone(REAL),checkId:'CHK-OTHER'}).key,original.key);assert.notEqual(make({...clone(REAL),contentHash:'f'.repeat(64)}).key,original.key);assert.equal(make({...clone(REAL),contentHash:'f'.repeat(64)}).type,original.type);});
 it('controller SSR starts with all63 and one chooser, no fetch or callback',()=>{const fetch=vi.spyOn(globalThis,'fetch').mockImplementation(()=>{throw Error('unexpected fetch');});const events:any[]=[],before=clone([REAL,OLD_FILES]);try{const html=renderToStaticMarkup(createElement(MatrixReviewWorklistController,{data:REAL,files:OLD_FILES,onSelect:(...v)=>events.push(v),onSource:v=>events.push(v)}));assert.equal((html.match(/Причина сохранённого результата:/g)||[]).length,63);assert.equal((html.match(/Искать в исходных файлах/g)||[]).length,1);assert.match(html,/Показано: 63 \/ 63/);assert.equal(fetch.mock.calls.length,0);assert.deepEqual(events,[]);assert.deepEqual([REAL,OLD_FILES],before);}finally{fetch.mockRestore();}});
 it('SSR controlled filtered render is honest about visible count, no qualification claims',()=>{const markup=renderToStaticMarkup(createElement(MatrixReviewWorklist,{data:REAL,files:OLD_FILES,view:view('BOTH_STAGES',true),onSelect:()=>{}}));assert.equal((markup.match(/Причина сохранённого результата:/g)||[]).length,2);assert.match(markup,/Показано: 2 \/ 63/);assert.match(markup,/Наличие фактов не подтверждает их сопоставимость, согласование или уверенность/);assert.doesNotMatch(markup.replace(/<[^>]*>/gu,' '),/Нарушений нет|Машинное предупреждение|NO_VIOLATION|80%|100%/);});
});
